public struct FfiArkMethod {
    public var label: String
    public var server: String
    public var pubkey: String
    public var vtxoPointer: String?
    public var opaqueUri: String?
    public var proof: FfiArkOwnershipProof?
    public var expiresAt: Int64?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(label: String, server: String, pubkey: String, vtxoPointer: String?, opaqueUri: String?, proof: FfiArkOwnershipProof?, expiresAt: Int64?) {
        self.label = label
        self.server = server
        self.pubkey = pubkey
        self.vtxoPointer = vtxoPointer
        self.opaqueUri = opaqueUri
        self.proof = proof
        self.expiresAt = expiresAt
    }
}

