extension FfiArkMethod: Sendable {}
#endif


extension FfiArkMethod: Equatable, Hashable {
    public static func ==(lhs: FfiArkMethod, rhs: FfiArkMethod) -> Bool {
        if lhs.label != rhs.label {
            return false
        }
        if lhs.server != rhs.server {
            return false
        }
        if lhs.pubkey != rhs.pubkey {
            return false
        }
        if lhs.vtxoPointer != rhs.vtxoPointer {
            return false
        }
        if lhs.opaqueUri != rhs.opaqueUri {
            return false
        }
        if lhs.proof != rhs.proof {
            return false
        }
        if lhs.expiresAt != rhs.expiresAt {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(label)
        hasher.combine(server)
        hasher.combine(pubkey)
        hasher.combine(vtxoPointer)
        hasher.combine(opaqueUri)
        hasher.combine(proof)
        hasher.combine(expiresAt)
    }
}



